package dev.dexdroid;

import android.app.*;
import android.content.*;
import android.content.res.*;
import android.graphics.*;
import android.os.*;
import android.view.*;
import android.widget.*;
import java.util.*;
import java.util.function.*;

/** Native monitor widgets laid out in virtual pixels, rotated with the desktop. */
final class MonitorShell {
 final FrameLayout root;
 private final SessionService session;
 private final Context displayContext;
 private Context context;
 private LinearLayout dock;
 private volatile String page="closed";
 private final ArrayDeque<String> history=new ArrayDeque<>();
 private final List<Runnable> updates=new ArrayList<>();
 private boolean updating,physicalUi,phoneUi,consuming;
 private String candidate="";
 private float startX,startY;
 private long physicalDown,phoneDown;
 private int lastW,lastH,lastDpi;
 private final Handler handler=new Handler(Looper.getMainLooper());
 private final Runnable tick=new Runnable(){public void run(){if(!page.equals("closed")){refresh();handler.postDelayed(this,750);}}};
 private final String[] rotations={"Landscape 0°","Portrait 90°","Landscape 180°","Portrait 270°"};
 MonitorShell(SessionService service,Context context){session=service;displayContext=context;root=new FrameLayout(context);root.setClipChildren(false);}
 private int dp(float value){return Math.round(value*session.dpi/160f);}
 void layout(int physicalW,int physicalH){
  int w=session.width(),h=session.height();
  if(lastW!=w||lastH!=h||lastDpi!=session.dpi){lastW=w;lastH=h;lastDpi=session.dpi;Configuration config=new Configuration(displayContext.getResources().getConfiguration());config.densityDpi=session.dpi;context=new ContextThemeWrapper(displayContext.createConfigurationContext(config),R.style.DexDroidTheme);root.setLayoutParams(new FrameLayout.LayoutParams(w,h));build();}
  float scale=Math.min((float)physicalW/(session.rotation%2==0?w:h),(float)physicalH/(session.rotation%2==0?h:w));
  root.setPivotX(w/2f);root.setPivotY(h/2f);root.setScaleX(scale);root.setScaleY(scale);root.setRotation(session.rotation*90f);root.setX((physicalW-w)/2f);root.setY((physicalH-h)/2f);
 }
 String page(){return page;}
 boolean physicalActive(){return physicalUi||consuming;}
 private RectF bounds(View child){float x=0,y=0;View current=child;while(current!=root){x+=current.getLeft()-current.getScrollX();y+=current.getTop()-current.getScrollY();if(!(current.getParent() instanceof View))break;current=(View)current.getParent();}return new RectF(x,y,x+child.getWidth(),y+child.getHeight());}
 private boolean hit(float x,float y){return !page.equals("closed")||(dock!=null&&bounds(dock).contains(x,y));}
 private Matrix inverse(float physicalW,float physicalH){float[] src={0,0,session.width(),0,session.width(),session.height(),0,session.height()},dst=new float[8];float[][] corners={{0,0},{1,0},{1,1},{0,1}};for(int i=0;i<4;i++){float[] p=Geometry.map(corners[i][0],corners[i][1],session.rotation,physicalW,physicalH,session.width(),session.height());dst[i*2]=p[0];dst[i*2+1]=p[1];}Matrix forward=new Matrix(),inverse=new Matrix();forward.setPolyToPoly(src,0,dst,0,4);forward.invert(inverse);return inverse;}
 boolean physical(MotionEvent event,float width,float height){
  if(!event.isFromSource(InputDevice.SOURCE_TOUCHSCREEN))return false;
  int action=event.getActionMasked();float[] p=Geometry.unmap(event.getX(),event.getY(),session.rotation,width,height,session.width(),session.height());
  if(action==MotionEvent.ACTION_DOWN){cancelAll();session.hideMonitorPointer();physicalDown=event.getEventTime();physicalUi=p!=null&&hit(p[0],p[1]);if(physicalUi){session.cancelPhoneInput();session.cancelMonitorGesture();}
   if(p!=null&&session.monitorNavigationEnabled()&&!session.busy){startX=p[0];startY=p[1];float zone=dp(20);candidate=startY<zone?"Controls":startY>session.height()-zone?"Home":startX<zone?"Left Back":startX>session.width()-zone?"Right Back":"";if(!candidate.isEmpty())session.log("Monitor edge candidate: "+candidate);}
  }
  if(consuming){if(action==MotionEvent.ACTION_UP||action==MotionEvent.ACTION_CANCEL){consuming=false;physicalUi=false;}return true;}
  if(!candidate.isEmpty()){
   if(event.getPointerCount()!=1||p==null||action==MotionEvent.ACTION_CANCEL||event.getEventTime()-physicalDown>1500){session.log("Monitor edge rejected: "+candidate+" (multi-touch, Fit bar, timeout, or cancel)");candidate="";}
   else if(action==MotionEvent.ACTION_MOVE||action==MotionEvent.ACTION_UP){float dx=p[0]-startX,dy=p[1]-startY;boolean vertical=candidate.equals("Home")||candidate.equals("Controls");float inward=candidate.equals("Home")?-dy:candidate.equals("Controls")?dy:candidate.equals("Right Back")?-dx:dx;float cross=vertical?Math.abs(dx):Math.abs(dy);
    if(inward>=dp(60)&&inward>=cross*1.4f){String recognized=candidate;candidate="";session.cancelMonitorGesture();if(physicalUi){MotionEvent cancel=MotionEvent.obtain(event);cancel.setAction(MotionEvent.ACTION_CANCEL);dispatchPhysical(cancel,width,height);cancel.recycle();}session.log("Monitor edge recognized: "+recognized+" dx="+Math.round(dx)+" dy="+Math.round(dy));if(recognized.equals("Home"))home();else if(recognized.equals("Controls"))show("controls");else if(isOpen())back();else session.key(KeyEvent.KEYCODE_BACK);consuming=action!=MotionEvent.ACTION_UP;physicalUi=false;return true;}
    if(cross>dp(30)&&cross>Math.abs(inward)*1.4f){session.log("Monitor edge rejected: "+candidate+" (perpendicular)");candidate="";}else if(action==MotionEvent.ACTION_UP){session.log("Monitor edge rejected: "+candidate+" (short or outward)");candidate="";}
   }
  }
  boolean owned=physicalUi;if(owned)dispatchPhysical(event,width,height);if(action==MotionEvent.ACTION_UP||action==MotionEvent.ACTION_CANCEL)physicalUi=false;return owned;
 }
 private void dispatchPhysical(MotionEvent original,float w,float h){MotionEvent mapped=MotionEvent.obtain(original);mapped.transform(inverse(w,h));root.dispatchTouchEvent(mapped);mapped.recycle();}
 boolean phone(int action,float[] xs,float[] ys){int masked=action&255;if(masked==MotionEvent.ACTION_DOWN){phoneUi=hit(xs[0],ys[0]);phoneDown=SystemClock.uptimeMillis();}if(!phoneUi)return false;MotionEvent event=event(phoneDown,action,xs,ys);root.dispatchTouchEvent(event);event.recycle();if(masked==MotionEvent.ACTION_UP||masked==MotionEvent.ACTION_CANCEL)phoneUi=false;return true;}
 boolean wheel(float x,float y,float dx,float dy){if(!hit(x,y))return false;MotionEvent.PointerProperties prop=new MotionEvent.PointerProperties();prop.id=0;prop.toolType=MotionEvent.TOOL_TYPE_MOUSE;MotionEvent.PointerCoords coords=new MotionEvent.PointerCoords();coords.x=x;coords.y=y;coords.setAxisValue(MotionEvent.AXIS_HSCROLL,dx);coords.setAxisValue(MotionEvent.AXIS_VSCROLL,dy);long now=SystemClock.uptimeMillis();MotionEvent event=MotionEvent.obtain(now,now,MotionEvent.ACTION_SCROLL,1,new MotionEvent.PointerProperties[]{prop},new MotionEvent.PointerCoords[]{coords},0,0,1,1,0,0,InputDevice.SOURCE_MOUSE,0);root.dispatchGenericMotionEvent(event);event.recycle();return true;}
 private MotionEvent event(long down,int action,float[] xs,float[] ys){MotionEvent.PointerProperties[] props=new MotionEvent.PointerProperties[xs.length];MotionEvent.PointerCoords[] coords=new MotionEvent.PointerCoords[xs.length];for(int i=0;i<xs.length;i++){props[i]=new MotionEvent.PointerProperties();props[i].id=i;props[i].toolType=MotionEvent.TOOL_TYPE_FINGER;coords[i]=new MotionEvent.PointerCoords();coords[i].x=xs[i];coords[i].y=ys[i];coords[i].pressure=1;}return MotionEvent.obtain(down,SystemClock.uptimeMillis(),action,xs.length,props,coords,0,0,1,1,0,0,InputDevice.SOURCE_TOUCHSCREEN,0);}
 void cancelPhone(){if(phoneUi){MotionEvent cancel=event(phoneDown,MotionEvent.ACTION_CANCEL,new float[]{0},new float[]{0});root.dispatchTouchEvent(cancel);cancel.recycle();}phoneUi=false;}
 void cancelAll(){cancelPhone();if(physicalUi){MotionEvent cancel=event(physicalDown,MotionEvent.ACTION_CANCEL,new float[]{0},new float[]{0});root.dispatchTouchEvent(cancel);cancel.recycle();}physicalUi=false;consuming=false;candidate="";}
 void destroy(){cancelAll();handler.removeCallbacks(tick);}
 boolean isOpen(){return !page.equals("closed");}
 void home(){history.clear();history.push("closed");page="home";build();session.log("Monitor Home: launcher opened");}
 void show(String next){if(!page.equals(next)){history.push(page);page=next;}build();session.log("Monitor panel opened: "+next);}
 void close(){history.clear();page="closed";build();}
 void back(){page=history.isEmpty()?"closed":history.pop();build();session.log("Monitor panel Back: "+page);}
 private android.graphics.drawable.Drawable surface(int shade){android.graphics.drawable.GradientDrawable d=new android.graphics.drawable.GradientDrawable();d.setColor(Color.rgb(shade,shade,shade));d.setCornerRadius(dp(12));d.setStroke(dp(1),Color.rgb(55,55,55));return d;}
 private TextView text(String value,int size){TextView view=new TextView(context);view.setText(value);view.setTextColor(Color.WHITE);view.setTextSize(size);return view;}
 private LinearLayout column(){LinearLayout view=new LinearLayout(context);view.setOrientation(LinearLayout.VERTICAL);return view;}
 private void section(LinearLayout parent,String value){TextView view=text(value,11);view.setTextColor(Color.GRAY);view.setPadding(0,dp(14),0,dp(6));parent.addView(view);}
 private Button button(LinearLayout row,String label,String tag,Runnable action){Button b=new Button(context);b.setText(label);b.setTag(tag);b.setContentDescription(label);b.setAllCaps(false);b.setTextColor(Color.WHITE);b.setTextSize(12);b.setMinWidth(0);b.setMinimumWidth(0);b.setMinimumHeight(0);b.setMinHeight(0);b.setPadding(dp(4),0,dp(4),0);b.setBackground(surface(24));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(48),1);lp.setMargins(dp(3),dp(4),dp(3),dp(4));row.addView(b,lp);b.setOnClickListener(v->action.run());return b;}
 private LinearLayout row(LinearLayout parent){LinearLayout row=new LinearLayout(context);parent.addView(row,new LinearLayout.LayoutParams(-1,-2));return row;}
 private void item(LinearLayout parent,String label,String tag,Supplier<String> value,Runnable action){Button b=new Button(context);b.setTag(tag);b.setAllCaps(false);b.setTextColor(Color.WHITE);b.setTextSize(13);b.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);b.setPadding(dp(12),dp(8),dp(12),dp(8));b.setBackground(surface(20));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(62));lp.topMargin=dp(6);parent.addView(b,lp);updates.add(()->{b.setText(label+"\n"+value.get());b.setContentDescription(label+", "+value.get());});b.setOnClickListener(v->{action.run();refresh();});}
 private void toggle(LinearLayout parent,String label,String tag,BooleanSupplier enabled,Consumer<Boolean> action){Switch view=new Switch(context);view.setTag(tag);view.setTextColor(Color.WHITE);view.setTextSize(13);view.setPadding(dp(10),0,dp(10),0);parent.addView(view,new LinearLayout.LayoutParams(-1,dp(54)));updates.add(()->{view.setText(label+" · "+(enabled.getAsBoolean()?"On":"Off"));view.setChecked(enabled.getAsBoolean());});view.setOnCheckedChangeListener((b,on)->{if(!updating){action.accept(on);refresh();}});}
 private String appName(){if(session.activePackage.isEmpty())return "No app selected";if(session.activePackage.equals(session.getPackageName()))return "DexDroid input test";try{return session.getPackageManager().getApplicationLabel(session.getPackageManager().getApplicationInfo(session.activePackage,0)).toString();}catch(Exception e){return session.activePackage;}}
 private String speed(){return session.scrollSpeed()<.35f?"Slow 20%":session.scrollSpeed()<.75f?"Normal 50%":"Fast 100%";}
 private void status(LinearLayout parent){TextView title=text("",14);title.setTypeface(null,Typeface.BOLD);parent.addView(title);TextView value=text("",12);value.setTextColor(Color.LTGRAY);value.setPadding(0,dp(6),0,dp(10));parent.addView(value);value.setTag("monitor-status");updates.add(()->{title.setText("Monitor · "+(session.external==null?"Disconnected":"Connected — "+session.external.getName()));String saved=session.prefs.contains("app."+session.activePackage)?rotations[session.prefs.getInt("app."+session.activePackage,0)]:"Default";value.setText("Shizuku · "+(session.needsRecovery()?"Unavailable":"Connected")+"   Desktop · "+(session.busy?"Updating":"Ready")+"\nApp · "+appName()+"\nScroll · "+(session.swipeScrolling()?"Swipe":"Wheel")+" · "+speed()+"\nRotation · "+rotations[session.rotation]+"   Saved · "+saved+"\nMonitor touch · "+(session.monitorTouchEnabled()?"On":"Off")+"   Edge navigation · "+(session.monitorNavigationEnabled()?"On":"Off")+"\n"+session.width()+" × "+session.height()+" · "+session.dpi+" UI DPI\n"+session.status.split("\\n",2)[0]);});}
 private void build(){if(context==null)return;handler.removeCallbacks(tick);updates.clear();root.removeAllViews();root.setBackgroundColor(page.equals("closed")?Color.TRANSPARENT:Color.argb(235,0,0,0));
  if(page.equals("closed")){dock=new LinearLayout(context);button(dock,"Apps","monitor-apps",this::home);button(dock,"Controls","monitor-controls",()->show("controls"));FrameLayout.LayoutParams lp=new FrameLayout.LayoutParams(dp(210),dp(56),Gravity.BOTTOM|Gravity.CENTER_HORIZONTAL);lp.bottomMargin=dp(8);root.addView(dock,lp);return;}
  dock=null;LinearLayout panel=column();panel.setPadding(dp(16),dp(12),dp(16),dp(12));panel.setBackground(surface(18));FrameLayout.LayoutParams lp=new FrameLayout.LayoutParams(Math.min(dp(500),session.width()-dp(24)),session.height()-dp(24),Gravity.CENTER);root.addView(panel,lp);
  LinearLayout header=row(panel);TextView heading=text(page.equals("home")?"DexDroid · Apps":page.equals("controls")?"Control panel":page.equals("rotation")?"Rotate":page.equals("scroll")?"Scrolling":page.equals("display")?"Resolution and DPI":page.equals("diagnostics")?"Diagnostic log":"Settings",20);header.addView(heading,new LinearLayout.LayoutParams(0,dp(54),1));button(header,"Close","monitor-close",this::back);
  if(page.equals("home")){List<AppCatalog.Entry> apps=AppCatalog.installed(session);ListView list=new ListView(context);list.setTag("monitor-app-list");list.setAdapter(new BaseAdapter(){public int getCount(){return apps.size();}public Object getItem(int p){return apps.get(p);}public long getItemId(int p){return p;}public View getView(int p,View old,ViewGroup group){AppCatalog.Entry app=apps.get(p);TextView view=text(app.name,15);view.setTag("app."+app.component.getPackageName());view.setPadding(dp(10),dp(12),dp(10),dp(12));app.icon.setBounds(0,0,dp(32),dp(32));view.setCompoundDrawables(app.icon,null,null,null);view.setCompoundDrawablePadding(dp(12));return view;}});panel.addView(list,new LinearLayout.LayoutParams(-1,0,1));list.setOnItemClickListener((p,v,index,id)->{AppCatalog.Entry app=apps.get(index);session.log("Monitor launcher selection: "+app.component.flattenToShortString());close();session.launch(app.component,null);});button(row(panel),"Resume app","monitor-resume",this::close);}
  else{ScrollView scroll=new ScrollView(context);LinearLayout body=column();scroll.addView(body);panel.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
   if(page.equals("controls")){status(body);LinearLayout first=row(body);button(first,"Apps","monitor-apps",this::home);button(first,"Rotate","monitor-rotate",()->show("rotation"));button(first,"Scroll","monitor-scroll",()->show("scroll"));button(first,"Save app","monitor-save",()->session.saveAppSettings());LinearLayout second=row(body);button(second,"Stop","monitor-stop",()->session.pauseDesktop());button(second,"Reset app","monitor-reset",()->session.resetAppSettings());button(second,"Settings","monitor-settings",()->show("settings"));button(second,"Back","monitor-back",this::back);}
   else if(page.equals("rotation")){for(int i=0;i<4;i++){final int selected=i;item(body,rotations[i],"monitor-rotation-"+i,()->session.rotation==selected?"Selected":"",()->{session.rotate(selected,true);back();});}}
   else if(page.equals("scroll")){if(session.activePackage.isEmpty())body.addView(text("Select an app before configuring scrolling",13));else{section(body,appName());item(body,"Swipe","monitor-swipe",()->session.swipeScrolling()?"Selected":"",()->session.setSwipeScrolling(true));item(body,"Wheel","monitor-wheel",()->!session.swipeScrolling()?"Selected":"",()->session.setSwipeScrolling(false));for(int i=0;i<3;i++){final int index=i;float rate=new float[]{.2f,.5f,1f}[i];item(body,new String[]{"Slow · 20%","Normal · 50%","Fast · 100%"}[i],"monitor-speed-"+i,()->Math.abs(session.scrollSpeed()-rate)<.01?"Selected":"",()->{session.prefs.edit().putFloat("scrollSpeed."+session.activePackage,new float[]{.2f,.5f,1f}[index]).apply();session.report("Monitor scroll speed saved");});}}}
   else if(page.equals("settings")){section(body,"DISPLAY");item(body,"Resolution and DPI","monitor-display",()->session.width()+" × "+session.height()+" · "+session.dpi+" DPI",()->show("display"));toggle(body,"Monitor touch","monitor-touch",()->session.monitorTouchEnabled(),session::setMonitorTouchEnabled);toggle(body,"Edge navigation","monitor-navigation",()->session.monitorNavigationEnabled(),session::setMonitorNavigationEnabled);section(body,"INPUT");item(body,"Pointer speed","monitor-pointer-speed",()->{float v=session.prefs.getFloat("speed",1.6f);return v<1.3?"Slow":v<2?"Normal":"Fast";},()->{float v=session.prefs.getFloat("speed",1.6f);session.prefs.edit().putFloat("speed",v<1.3f?1.6f:v<2?2.5f:1).apply();session.report("Pointer speed changed from monitor");});toggle(body,"Reverse scroll direction","monitor-reverse",()->session.prefs.getBoolean("reverseScroll",false),on->{session.prefs.edit().putBoolean("reverseScroll",on).apply();session.report("Scroll direction changed from monitor");});item(body,"Center pointer","monitor-center",()->"Recenter on desktop",session::center);section(body,"GENERAL");item(body,"Background operation","monitor-background",()->(session.backgroundProtectionEnabled()?"Allowed":"Restricted")+" · Configure on phone",()->{Intent intent=session.backgroundProtectionEnabled()?new Intent(android.provider.Settings.ACTION_IGNORE_BATTERY_OPTIMIZATION_SETTINGS):new Intent(android.provider.Settings.ACTION_REQUEST_IGNORE_BATTERY_OPTIMIZATIONS,android.net.Uri.parse("package:"+session.getPackageName()));ActivityOptions options=ActivityOptions.makeBasic();options.setLaunchDisplayId(Display.DEFAULT_DISPLAY);session.startActivity(intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK),options.toBundle());});item(body,"Diagnostic log","monitor-diagnostics",()->"Gesture and connection events",()->show("diagnostics"));item(body,"Reset monitor profile","monitor-reset-profile",()->session.prefs.contains(session.monitorKey()+".w")?"Saved profile":"Default profile",session::resetMonitor);}
   else if(page.equals("display")){body.addView(text(session.capabilities(),12));if(session.external!=null){Display.Mode mode=session.external.getMode();item(body,"Same as output","monitor-native",()->mode.getPhysicalWidth()+" × "+mode.getPhysicalHeight(),()->session.preview(mode.getPhysicalWidth(),mode.getPhysicalHeight(),Geometry.recommendedDpi(Math.min(mode.getPhysicalWidth(),mode.getPhysicalHeight()))));item(body,"Lower rendering load","monitor-low",()->Math.round(mode.getPhysicalWidth()*2f/3)+" × "+Math.round(mode.getPhysicalHeight()*2f/3),()->{int w=Math.round(mode.getPhysicalWidth()*2f/3),h=Math.round(mode.getPhysicalHeight()*2f/3);session.preview(w,h,Geometry.recommendedDpi(Math.min(w,h)));});for(int value:new int[]{160,240,320})item(body,"UI DPI "+value,"monitor-dpi-"+value,()->session.dpi==value?"Selected":"",()->session.preview(session.baseW,session.baseH,value));}}
   else if(page.equals("diagnostics")){TextView log=text("",11);log.setTypeface(Typeface.MONOSPACE);log.setTextIsSelectable(true);body.addView(log);updates.add(()->log.setText(session.diagnosticText()));LinearLayout actions=row(body);button(actions,"Copy","monitor-log-copy",()->((ClipboardManager)session.getSystemService(Context.CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("DexDroid diagnostics",session.diagnosticText())));button(actions,"Clear","monitor-log-clear",session::clearDiagnostics);}
   LinearLayout keep=row(body);keep.setTag("monitor-confirmation");button(keep,"Keep","monitor-keep",()->session.confirm(true));button(keep,"Revert","monitor-revert",()->session.confirm(false));updates.add(()->keep.setVisibility(session.awaitingConfirmation()?View.VISIBLE:View.GONE));
  }
  refresh();handler.postDelayed(tick,750);
 }
 void refresh(){updating=true;try{for(Runnable update:updates)update.run();}finally{updating=false;}}
}
